1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code identityKey} — the single value all duplicate detection is expressed
12	 * through.
13	 *
14	 * <p>The key is the lower-case hex SHA-256 over
15	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners are duplicates
16	 * only when their keys are equal (see {@link CheckIdentityUnique}). Because the telephone is part of
17	 * the key, two owners with the same last name and postcode but different telephones have different
18	 * keys and are both allowed — the second is created as a soft match (see {@link PossibleDuplicate}).
19	 *
20	 * <p>The three components are normalized so the key is stable: the telephone to E.164 form (see
21	 * {@link TelephoneE164}), the email lower-cased and trimmed, and the last name reduced to its Soundex
22	 * code so equivalent-sounding surnames share it.
23	 */
24	public final class OwnerIdentity {
25	
26	    private OwnerIdentity() {
27	    }
28	
29	    /** The identity key of a persisted owner, from its stored telephone, email and last name. */
30	    public static String of(Owner owner) {
31	        return key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
32	    }
33	
34	    /**
35	     * The owner's current <em>primary identifier</em> — the single externally-visible handle an owner
36	     * is known by. That is the {@code memberId} (the unified {@code <REGION><FY><HASH8><CHK>} identity,
37	     * see {@link MemberId}), so everything expressed through the primary identifier (e.g. the
38	     * {@code OWNER_CREATED} structured event, see {@link OwnerCreatedEvent}) follows from it.
39	     */
40	    public static String primaryIdentifier(Owner owner) {
41	        return owner.getMemberId();
42	    }
43	
44	    /**
45	     * Assemble the identity key: the lower-case hex SHA-256 over the normalized telephone, lower-cased
46	     * email and Soundex of the last name, joined by {@code '|'}.
47	     */
48	    public static String key(String telephone, String email, String lastName) {
49	        return sha256HexFull(normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
50	                + soundex(lastName));
51	    }
52	
53	    /**
54	     * The stable, shared household identifier for an owner's last name and postcode: the first 12
55	     * upper-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (last name
56	     * lower-cased with whitespace collapsed; postcode trimmed). Owners with the same last name and
57	     * postcode get the same value automatically, regardless of creation order, so the household is
58	     * keyed on {@code (lastName, postcode)}. Returns {@code null} when there is no postcode — an owner
59	     * without a postcode is not in any household.
60	     */
61	    public static String householdIdFor(String lastName, String postcode) {
62	        String normalizedPostcode = normalizePostcode(postcode);
63	        if (normalizedPostcode == null) {
64	            return null;
65	        }
66	        return sha256Hex(normalizeLastName(lastName) + "|" + normalizedPostcode, 12);
67	    }
68	
69	    /**
70	     * The HASH8 segment of an owner's {@code memberId}: the first 8 upper-case hex characters of
71	     * SHA-256 over {@code normalizedTelephone + lastName}. The telephone is normalized to E.164 form
72	     * (null/invalid becomes empty) so the hash is stable across equivalent phone formats; the last
73	     * name is taken as stored.
74	     */
75	    public static String memberIdHash(String telephone, String lastName) {
76	        return sha256Hex(normalizeTelephone(telephone) + (lastName == null ? "" : lastName), 8);
77	    }
78	
79	    /**
80	     * The American Soundex code of a last name: the retained first letter followed by up to three
81	     * digits, zero-padded to length 4 (e.g. {@code "Robert" -> "R163"}). Letters are coded
82	     * B,F,P,V=1; C,G,J,K,Q,S,X,Z=2; D,T=3; L=4; M,N=5; R=6; vowels and Y are ignored; adjacent letters
83	     * with the same code (and letters separated only by H or W) collapse to one digit. A null or
84	     * letter-less name yields the empty string, so such owners simply share the "no surname" bucket.
85	     */
86	    public static String soundex(String lastName) {
87	        if (lastName == null) {
88	            return "";
89	        }
90	        StringBuilder letters = new StringBuilder();
91	        for (int i = 0; i < lastName.length(); i++) {
92	            char c = lastName.charAt(i);
93	            if (Character.isLetter(c)) {
94	                letters.append(Character.toUpperCase(c));
95	            }
96	        }
97	        if (letters.length() == 0) {
98	            return "";
99	        }
100	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
101	        char lastCode = soundexCode(letters.charAt(0));
102	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
103	            char c = letters.charAt(i);
104	            if (c == 'H' || c == 'W') {
105	                continue; // H and W never separate two same-coded consonants
106	            }
107	            char digit = soundexCode(c);
108	            if (digit != '0' && digit != lastCode) {
109	                code.append(digit);
110	            }
111	            lastCode = digit; // vowels ('0') reset, so a following same-coded consonant is coded
112	        }
113	        while (code.length() < 4) {
114	            code.append('0');
115	        }
116	        return code.toString();
117	    }
118	
119	    /** The Soundex digit for a letter, or {@code '0'} for vowels, Y and any uncoded letter. */
120	    private static char soundexCode(char c) {
121	        switch (c) {
122	            case 'B': case 'F': case 'P': case 'V':
123	                return '1';
124	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
125	                return '2';
126	            case 'D': case 'T':
127	                return '3';
128	            case 'L':
129	                return '4';
130	            case 'M': case 'N':
131	                return '5';
132	            case 'R':
133	                return '6';
134	            default:
135	                return '0';
136	        }
137	    }
138	
139	    /** Full lower-case hex SHA-256 over the UTF-8 bytes of {@code input} (64 characters). */
140	    private static String sha256HexFull(String input) {
141	        try {
142	            byte[] digest = MessageDigest.getInstance("SHA-256")
143	                    .digest(input.getBytes(StandardCharsets.UTF_8));
144	            StringBuilder sb = new StringBuilder(64);
145	            for (byte b : digest) {
146	                sb.append(String.format("%02x", b));
147	            }
148	            return sb.toString();
149	        }
150	        catch (NoSuchAlgorithmException e) {
151	            throw new IllegalStateException("SHA-256 not available", e);
152	        }
153	    }
154	
155	    /** First {@code length} upper-case hex chars of SHA-256 over the UTF-8 bytes of {@code input}. */
156	    private static String sha256Hex(String input, int length) {
157	        try {
158	            byte[] digest = MessageDigest.getInstance("SHA-256")
159	                    .digest(input.getBytes(StandardCharsets.UTF_8));
160	            StringBuilder sb = new StringBuilder(64);
161	            for (byte b : digest) {
162	                sb.append(String.format("%02x", b));
163	            }
164	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
165	        }
166	        catch (NoSuchAlgorithmException e) {
167	            throw new IllegalStateException("SHA-256 not available", e);
168	        }
169	    }
170	
171	    /** Telephone in E.164 form for comparison; null/invalid becomes empty. */
172	    private static String normalizeTelephone(String telephone) {
173	        String e164 = TelephoneE164.normalize(telephone);
174	        return e164 == null ? "" : e164;
175	    }
176	
177	    /** Email lower-cased and trimmed so comparison ignores case; null/blank becomes empty. */
178	    private static String normalizeEmail(String email) {
179	        if (email == null) {
180	            return "";
181	        }
182	        return email.trim().toLowerCase(Locale.ROOT);
183	    }
184	
185	    /** Last name lower-cased with runs of whitespace collapsed, so comparison ignores case/spacing. */
186	    private static String normalizeLastName(String value) {
187	        if (value == null) {
188	            return "";
189	        }
190	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
191	    }
192	
193	    /** Postcode trimmed; null or blank becomes null (no household). */
194	    private static String normalizePostcode(String postcode) {
195	        if (postcode == null) {
196	            return null;
197	        }
198	        String trimmed = postcode.trim();
199	        return trimmed.isEmpty() ? null : trimmed;
200	    }
201	}
202

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Fixed city-to-region lookup used to derive an owner's {@code locality}.
8	 *
9	 * <p>The table is intentionally closed: only Sydney, Melbourne and Brisbane map to a
10	 * canonical region. Any other (or missing) city derives the locality {@code "UNKNOWN"}.
11	 */
12	public final class CityRegion {
13	
14	    /** City (case-insensitive) -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	        "sydney", "NSW",
17	        "melbourne", "VIC",
18	        "brisbane", "QLD");
19	
20	    /** Region -> inclusive {low, high} 4-digit postcode range. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	        "NSW", new int[] {2000, 2099},
23	        "VIC", new int[] {3000, 3099},
24	        "QLD", new int[] {4000, 4099});
25	
26	    /** Region -> IANA timezone name. */
27	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
28	        "NSW", "Australia/Sydney",
29	        "VIC", "Australia/Melbourne",
30	        "QLD", "Australia/Brisbane");
31	
32	    /** Locality returned when the city is not in {@link #CITY_REGION}. */
33	    public static final String UNKNOWN = "UNKNOWN";
34	
35	    private CityRegion() {
36	    }
37	
38	    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not in the table. */
39	    public static String localityOf(String city) {
40	        if (city == null) {
41	            return UNKNOWN;
42	        }
43	        return CITY_REGION.getOrDefault(city.trim().toLowerCase(Locale.ROOT), UNKNOWN);
44	    }
45	
46	    /**
47	     * The canonical region, preferring the {@code postcode}: the region whose range contains the
48	     * postcode is returned first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). Only when the
49	     * postcode is absent, non-numeric or in no known range does this fall back to the city-to-region
50	     * table. Returns {@code "UNKNOWN"} when neither yields a region.
51	     */
52	    public static String localityOf(String city, String postcode) {
53	        String byPostcode = regionForPostcode(postcode);
54	        return byPostcode != null ? byPostcode : localityOf(city);
55	    }
56	
57	    /** The region whose inclusive range contains {@code postcode}, or {@code null} when none does. */
58	    private static String regionForPostcode(String postcode) {
59	        if (postcode == null) {
60	            return null;
61	        }
62	        int value;
63	        try {
64	            value = Integer.parseInt(postcode.trim());
65	        }
66	        catch (NumberFormatException ex) {
67	            return null;
68	        }
69	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
70	            int[] range = entry.getValue();
71	            if (value >= range[0] && value <= range[1]) {
72	                return entry.getKey();
73	            }
74	        }
75	        return null;
76	    }
77	
78	    /**
79	     * The inclusive {@code {low, high}} postcode range for {@code city}'s region, or {@code null}
80	     * when the city has no known region (in which case any 4-digit postcode is accepted).
81	     */
82	    public static int[] postcodeRangeOf(String city) {
83	        return REGION_POSTCODES.get(localityOf(city));
84	    }
85	
86	    /**
87	     * An owner's {@code locality}, now the REGION segment of its {@code memberId}
88	     * ({@code <REGION><FY><HASH8><CHK>}). The region is the leading known region code (NSW, VIC, QLD
89	     * or UNKNOWN) the id starts with. When the id is absent or not in that shape (e.g. an owner not
90	     * created through the member-id pipeline), falls back to deriving the region from the city and
91	     * postcode directly.
92	     */
93	    public static String localityOfMemberId(String memberId, String city, String postcode) {
94	        if (memberId != null) {
95	            for (String region : REGION_POSTCODES.keySet()) {
96	                if (memberId.startsWith(region)) {
97	                    return region;
98	                }
99	            }
100	            if (memberId.startsWith(UNKNOWN)) {
101	                return UNKNOWN;
102	            }
103	        }
104	        return localityOf(city, postcode);
105	    }
106	
107	    /**
108	     * The IANA timezone name for the owner's locality/region, derived the same way as
109	     * {@link #localityOfMemberId(String, String, String)}, via the fixed region-to-timezone
110	     * table (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane).
111	     * Returns {@code null} when the region is {@code "UNKNOWN"} (not in the table).
112	     */
113	    public static String timezoneOfMemberId(String memberId, String city, String postcode) {
114	        return REGION_TIMEZONE.get(localityOfMemberId(memberId, city, postcode));
115	    }
116	}
