1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Assembles and inspects an owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>}:
5	 * the region code (see {@link CityRegion}), the 2-digit fiscal year FY of the registrationDate
6	 * (see {@link FiscalYear}), the 8 upper-case hex HASH8 of SHA-256 over {@code normalizedTelephone +
7	 * lastName} (see {@link OwnerIdentity#memberIdHash}) and a single Luhn check digit CHK computed over
8	 * the digits of {@code <REGION><FY><HASH8>}. For example {@code NSW261A2B3C4D7}.
9	 *
10	 * <p>The base id depends only on this owner's own fields and is stable regardless of how many owners
11	 * exist; collision handling (see {@link AssignMemberId}) de-duplicates it by appending {@code -<n>}.
12	 */
13	public final class MemberId {
14	
15	    private MemberId() {
16	    }
17	
18	    /**
19	     * The base {@code memberId} (before any collision suffix) from its {@code region}, 2-digit fiscal
20	     * year {@code fiscalYearYY} and {@code hash8}: {@code <REGION><FY><HASH8>} with the Luhn CHK of its
21	     * digits appended.
22	     */
23	    public static String of(String region, int fiscalYearYY, String hash8) {
24	        String body = String.format("%s%02d%s", region, fiscalYearYY, hash8);
25	        return body + luhn(body);
26	    }
27	
28	    /**
29	     * The Luhn check digit (0-9) over the digits contained in {@code value}; non-digit characters are
30	     * ignored. Working right-to-left, every second digit starting from the rightmost is doubled
31	     * (subtracting 9 when the result exceeds 9); the check digit brings the running total to the next
32	     * multiple of ten.
33	     */
34	    public static int luhn(String value) {
35	        int sum = 0;
36	        boolean doubleDigit = true;
37	        for (int i = value.length() - 1; i >= 0; i--) {
38	            char c = value.charAt(i);
39	            if (c < '0' || c > '9') {
40	                continue;
41	            }
42	            int d = c - '0';
43	            if (doubleDigit) {
44	                d *= 2;
45	                if (d > 9) {
46	                    d -= 9;
47	                }
48	            }
49	            sum += d;
50	            doubleDigit = !doubleDigit;
51	        }
52	        return (10 - (sum % 10)) % 10;
53	    }
54	}
