1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
6	
7	/**
8	 * Derives an owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>} — one of
9	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
10	 * {@code STANDARD_REGIONAL}.
11	 *
12	 * <ul>
13	 *   <li>TIER is {@code PREMIUM} when the owner's {@link MembershipLevel} is {@code 3} or more,
14	 *       otherwise {@code STANDARD}.</li>
15	 *   <li>AREA is {@code METRO} when the owner's locality (see {@link CityRegion}) is a known region
16	 *       (NSW, VIC or QLD), otherwise {@code REGIONAL}.</li>
17	 * </ul>
18	 */
19	public final class OwnerSegment {
20	
21	    private static final int PREMIUM_MIN_LEVEL = 3;
22	
23	    private OwnerSegment() {
24	    }
25	
26	    /** The owner's segment, formatted {@code <TIER>_<AREA>}. */
27	    public static OwnerDto.OwnerSegmentEnum of(Owner owner, OwnerRepository ownerRepository) {
28	        String tier = MembershipLevel.of(owner, ownerRepository) >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
29	        String locality = CityRegion.localityOfMemberId(owner.getMemberId(), owner.getCity(),
30	            owner.getPostcode());
31	        String area = CityRegion.UNKNOWN.equals(locality) ? "REGIONAL" : "METRO";
32	        return OwnerDto.OwnerSegmentEnum.valueOf(tier + "_" + area);
33	    }
34	}
