1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} (see
12	 * {@link MemberId}): REGION is the region code derived from the postcode/city (see
13	 * {@link CityRegion#localityOf(String, String)}), FY is the 2-digit fiscal year of the
14	 * registrationDate (see {@link FiscalYear}), HASH8 is the first 8 upper-case hex characters of
15	 * SHA-256 over {@code normalizedTelephone + lastName} (see {@link OwnerIdentity#memberIdHash}) and
16	 * CHK is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}. For example
17	 * {@code NSW261A2B3C4D7}.
18	 *
19	 * <p>Runs after {@link BuildOwner} (which defaults the registration date) and
20	 * {@link ResolveRegistrationDate}, so the fiscal year is known. The base id depends only on this
21	 * owner's own fields and is stable regardless of how many owners exist. When that base collides with
22	 * an existing owner's {@code memberId}, this step de-duplicates it by appending {@code -<n>} with the
23	 * smallest {@code n} of 2 or more that makes it unique (e.g. {@code NSW261A2B3C4D7-2}). Every value
24	 * derived from the member id — the create audit line (see {@link AuditOwnerCreated}), the response
25	 * {@code locality} and the {@code ownerSegment} — follows the de-duplicated id.
26	 */
27	public class AssignMemberId {
28	
29	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
30	        String region = CityRegion.localityOf(owner.getCity(), owner.getPostcode());
31	        int fiscalYearYY = FiscalYear.endingYearOf(owner.getRegistrationDate()) % 100;
32	        String hash8 = OwnerIdentity.memberIdHash(owner.getTelephone(), owner.getLastName());
33	        String base = MemberId.of(region, fiscalYearYY, hash8);
34	
35	        Set<String> existing = new HashSet<>();
36	        for (Owner other : ownerRepository.findAll()) {
37	            if (other.getMemberId() != null) {
38	                existing.add(other.getMemberId());
39	            }
40	        }
41	
42	        String memberId = base;
43	        for (int n = 2; existing.contains(memberId); n++) {
44	            memberId = base + "-" + n;
45	        }
46	        owner.setMemberId(memberId);
47	    }
48	}
