1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Derives fiscal-year values from a date. The fiscal year runs 1 July to 30 June and is named by the
8	 * calendar year it ends in: a date on or after 1 July belongs to the fiscal year ending the following
9	 * June (e.g. {@code 2025-08-16} is in the fiscal year ending June 2026, labelled {@code FY26}), and a
10	 * date before 1 July belongs to the fiscal year ending that same June.
11	 *
12	 * <p>All date-derived owner values that were previously on a calendar-year basis now use this: the
13	 * {@code fiscalYear} label returned on the DTO, the {@code memberId}'s FY segment
14	 * (see {@link AssignMemberId}) and the tenure count (see {@link MembershipLevel}). Every one
15	 * is measured from the business-day-adjusted {@code registrationDate} resolved at creation
16	 * (see {@link ResolveRegistrationDate}).
17	 */
18	public final class FiscalYear {
19	
20	    private FiscalYear() {
21	    }
22	
23	    /** The calendar year the fiscal year containing {@code date} ends in (e.g. 2026 for {@code FY26}). */
24	    public static int endingYearOf(LocalDate date) {
25	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
26	    }
27	
28	    /** The fiscal-year label for {@code date}, formatted {@code FY<YY>} (e.g. {@code FY26}); {@code null} when the date is absent. */
29	    public static String labelOf(LocalDate date) {
30	        if (date == null) {
31	            return null;
32	        }
33	        return String.format("FY%02d", endingYearOf(date) % 100);
34	    }
35	
36	    /** Elapsed whole fiscal years between {@code from} and {@code to} (0 within the same fiscal year). */
37	    public static int elapsedYears(LocalDate from, LocalDate to) {
38	        return endingYearOf(to) - endingYearOf(from);
39	    }
40	}
