1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * The immutable {@code OWNER_CREATED} structured audit event, emitted alongside the human-readable
10	 * audit line (see {@link AuditOwnerCreated}) whenever an owner is created.
11	 *
12	 * <p>Serialized to JSON as
13	 * {@code {"seq":<n>,"ownerId":<id>,"customerCode":<identifier>,"membershipLevel":<level>,"event":"OWNER_CREATED"}}.
14	 * The {@code seq} is a process-wide monotonically increasing integer across all creates. The
15	 * {@code customerCode} carries the owner's <em>current primary identifier</em> (see
16	 * {@link OwnerIdentity#primaryIdentifier(Owner)}) — the {@code customerCode} today, and whatever
17	 * replaces it later (the {@code memberId}), without this event needing to change.
18	 */
19	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, int membershipLevel) {
20	
21	    /** The {@code event} discriminator carried by every owner-created event. */
22	    public static final String EVENT = "OWNER_CREATED";
23	
24	    /** Process-wide sequence source; each created owner's event gets the next value. */
25	    private static final AtomicLong SEQUENCE = new AtomicLong(0);
26	
27	    /** Build the next event for a persisted {@code owner}, allocating a fresh {@link #seq()}. */
28	    public static OwnerCreatedEvent forOwner(Owner owner, OwnerRepository ownerRepository) {
29	        return new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
30	                OwnerIdentity.primaryIdentifier(owner), MembershipLevel.of(owner, ownerRepository));
31	    }
32	
33	    /** The event as a single-line JSON object, in the field order stated on the type. */
34	    public String toJson() {
35	        return "{\"seq\":" + this.seq
36	                + ",\"ownerId\":" + this.ownerId
37	                + ",\"customerCode\":" + jsonString(this.customerCode)
38	                + ",\"membershipLevel\":" + this.membershipLevel
39	                + ",\"event\":" + jsonString(EVENT)
40	                + "}";
41	    }
42	
43	    /** A JSON string literal for {@code value} ({@code null} becomes JSON {@code null}). */
44	    private static String jsonString(String value) {
45	        if (value == null) {
46	            return "null";
47	        }
48	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
49	        for (int i = 0; i < value.length(); i++) {
50	            char c = value.charAt(i);
51	            switch (c) {
52	                case '"': sb.append("\\\""); break;
53	                case '\\': sb.append("\\\\"); break;
54	                case '\n': sb.append("\\n"); break;
55	                case '\r': sb.append("\\r"); break;
56	                case '\t': sb.append("\\t"); break;
57	                default:
58	                    if (c < 0x20) {
59	                        sb.append(String.format("\\u%04x", (int) c));
60	                    }
61	                    else {
62	                        sb.append(c);
63	                    }
64	            }
65	        }
66	        return sb.append('"').toString();
67	    }
68	}
