1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Rejects creating an owner that duplicates an existing one, so the create endpoint responds 409
11	 * instead of storing a duplicate. Duplicate detection is the single identity key: the new owner's
12	 * identity key (the SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
13	 * see {@link OwnerIdentity}) equals an existing owner's. This is genuinely the same person and is
14	 * always rejected.
15	 *
16	 * <p>Because the telephone is part of the key, two owners with the same last name and postcode but
17	 * different telephones have different keys and are <em>not</em> rejected — the second is created as a
18	 * soft match (see {@link PossibleDuplicate}). There is no separate household-duplicate rule.
19	 *
20	 * <p>Runs after {@link ValidateOwner} (which normalizes and publishes the body, and applies the
21	 * email-domain blocklist first) and before {@link BuildOwner}, comparing against every existing owner
22	 * and ignoring any flagged deleted.
23	 */
24	public class CheckIdentityUnique {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(),
29	                request.getLastName());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            // A soft-deleted owner is not a live duplicate: skip it so its identity frees up.
32	            if (existing.isDeleted()) {
33	                continue;
34	            }
35	            if (identityKey.equals(OwnerIdentity.of(existing))) {
36	                throw new DuplicateIdentityException(identityKey);
37	            }
38	        }
39	    }
40	}
