2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Detects a <em>soft</em> duplicate: an existing owner whose {@code lastName} has the same Soundex
8	 * code as this owner's and shares this owner's {@code postcode}, but whose identity key differs.
9	 *
10	 * <p>Such an owner is deliberately still created — unlike a hard duplicate, whose whole identity key
11	 * matches an existing owner's and is rejected with 409 (see {@link CheckIdentityUnique}). Because the
12	 * telephone is part of the identity key, two owners with the same last name and postcode but different
13	 * telephones have different keys, so the second is a soft match rather than a rejected duplicate.
14	 *
15	 * <p>The response surfaces the match through {@code possibleDuplicate} / {@code possibleDuplicateOf}.
16	 * The earliest (lowest id) matching owner is reported so the result is stable.
17	 */
18	public final class PossibleDuplicate {
19	
20	    private PossibleDuplicate() {
21	    }
22	
23	    /**
24	     * The id of an existing owner whose last name shares {@code owner}'s Soundex code and whose
25	     * postcode matches, but whose identity key differs, or {@code null} when there is no such match
26	     * (including when the owner has no postcode).
27	     */
28	    public static Integer matchFor(Owner owner, OwnerRepository ownerRepository) {
29	        String postcode = normalizePostcode(owner.getPostcode());
30	        if (postcode == null) {
31	            return null;
32	        }
33	        String soundex = OwnerIdentity.soundex(owner.getLastName());
34	        String identityKey = OwnerIdentity.of(owner);
35	        Integer match = null;
36	        for (Owner other : ownerRepository.findAll()) {
37	            if (other.getId() == null || other.getId().equals(owner.getId())) {
38	                continue;
39	            }
40	            if (!postcode.equals(normalizePostcode(other.getPostcode()))) {
41	                continue;
42	            }
43	            if (!soundex.equals(OwnerIdentity.soundex(other.getLastName()))) {
44	                continue;
45	            }
46	            if (identityKey.equals(OwnerIdentity.of(other))) {
47	                continue; // same identity key would be a hard duplicate, not a soft match
48	            }
49	            if (match == null || other.getId() < match) {
50	                match = other.getId();
51	            }
52	        }
53	        return match;
54	    }
55	
56	    private static String normalizePostcode(String postcode) {
57	        if (postcode == null) {
58	            return null;
59	        }
60	        String trimmed = postcode.trim();
61	        return trimmed.isEmpty() ? null : trimmed;
62	    }
63	}
