8	 *
9	 * <p>The table is intentionally closed: only Sydney, Melbourne and Brisbane map to a
10	 * canonical region. Any other (or missing) city derives the locality {@code "UNKNOWN"}.
11	 */
12	public final class CityRegion {
13	
14	    /** City (case-insensitive) -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	        "sydney", "NSW",
17	        "melbourne", "VIC",
18	        "brisbane", "QLD");
19	
20	    /** Region -> inclusive {low, high} 4-digit postcode range. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	        "NSW", new int[] {2000, 2099},
23	        "VIC", new int[] {3000, 3099},
24	        "QLD", new int[] {4000, 4099});
25	
26	    /** Region -> IANA timezone name. */
27	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
28	        "NSW", "Australia/Sydney",
29	        "VIC", "Australia/Melbourne",
30	        "QLD", "Australia/Brisbane");
31	
32	    /** Locality returned when the city is not in {@link #CITY_REGION}. */
33	    public static final String UNKNOWN = "UNKNOWN";
34	
35	    private CityRegion() {
36	    }
37	
38	    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not in the table. */
39	    public static String localityOf(String city) {
40	        if (city == null) {
41	            return UNKNOWN;
42	        }
43	        return CITY_REGION.getOrDefault(city.trim().toLowerCase(Locale.ROOT), UNKNOWN);
44	    }
45	
46	    /**
47	     * The canonical region, preferring the {@code postcode}: the region whose range contains the
48	     * postcode is returned first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). Only when the
49	     * postcode is absent, non-numeric or in no known range does this fall back to the city-to-region
50	     * table. Returns {@code "UNKNOWN"} when neither yields a region.
51	     */
52	    public static String localityOf(String city, String postcode) {
53	        String byPostcode = regionForPostcode(postcode);
54	        return byPostcode != null ? byPostcode : localityOf(city);
55	    }
56	
57	    /** The region whose inclusive range contains {@code postcode}, or {@code null} when none does. */
58	    private static String regionForPostcode(String postcode) {
59	        if (postcode == null) {
60	            return null;
61	        }
62	        int value;
63	        try {
64	            value = Integer.parseInt(postcode.trim());
65	        }
66	        catch (NumberFormatException ex) {
67	            return null;
68	        }
69	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
70	            int[] range = entry.getValue();
71	            if (value >= range[0] && value <= range[1]) {
72	                return entry.getKey();
73	            }
74	        }
75	        return null;
76	    }
