88	     * ({@code <REGION><FY><HASH8><CHK>}). The region is the leading known region code (NSW, VIC, QLD
89	     * or UNKNOWN) the id starts with. When the id is absent or not in that shape (e.g. an owner not
90	     * created through the member-id pipeline), falls back to deriving the region from the city and
91	     * postcode directly.
92	     */
93	    public static String localityOfMemberId(String memberId, String city, String postcode) {
94	        if (memberId != null) {
95	            for (String region : REGION_POSTCODES.keySet()) {
96	                if (memberId.startsWith(region)) {
97	                    return region;
98	                }
99	            }
100	            if (memberId.startsWith(UNKNOWN)) {
101	                return UNKNOWN;
102	            }
103	        }
104	        return localityOf(city, postcode);
